read_libraries <- function() {
  lib <- utils::read.csv(input_path("metadata", "wgbs_libraries.csv"), stringsAsFactors = FALSE)
  lib <- lib[order(lib$legacy_sample_index), ]
  stopifnot(nrow(lib) == 22, !anyDuplicated(lib$library_id))
  bad_sheet <- function(...) stop("wgbs_libraries.csv: ", sprintf(...), call. = FALSE)
  if (!isTRUE(all.equal(lib$legacy_sample_index, 1:22))) bad_sheet("legacy_sample_index must hold the integers 1 to 22, each once")
  for (column in c("ploidy", "treatment")) {
    allowed <- list(ploidy = c("diploid", "triploid"), treatment = c("control", "heat"))[[column]]
    bad <- setdiff(unique(lib[[column]]), allowed)
    if (length(bad) > 0) bad_sheet("column '%s' may hold only %s; found %s (%d row(s))", column,
                                   paste(sprintf("'%s'", allowed), collapse = " and "),
                                   paste(sprintf("'%s'", bad), collapse = ", "), sum(!lib[[column]] %in% allowed))
  }
  if (any(table(lib$ploidy, lib$treatment) == 0)) bad_sheet("every combination of ploidy and treatment needs at least one library")
  lib$ploidy    <- factor(lib$ploidy, levels = c("diploid", "triploid"))
  lib$treatment <- factor(lib$treatment, levels = c("control", "heat"))
  lib$group     <- factor(paste(lib$ploidy, lib$treatment),
                          levels = c("diploid control", "diploid heat", "triploid control", "triploid heat"))
  rownames(lib) <- NULL
  lib
}

